const int maxn = 5e4 + 10;
int lg[maxn];
struct SA {
    char s[maxn];
    int rk[maxn], sa[maxn], c[maxn], x[maxn], y[maxn], h[maxn], n, m, st[maxn][20];
    void init() {
        memset(x, 0, sizeof x);
        memset(y, 0, sizeof y);
        memset(h, 0, sizeof h);
        memset(st, 0, sizeof st);
        memset(sa, 0, sizeof sa);
        memset(rk, 0, sizeof rk);
        memset(c, 0, sizeof c);
        for(int i = 1; i <= n; i++) x[i] = y[i] = h[i] = st[i][0] = sa[i] = rk[i] = 0;
        for(int i = 1; i <= m; i++) c[i] = 0;
        for(int i = 1; i <= n; i++) c[x[i] = s[i]]++;
        for(int i = 1; i <= m; i++) c[i] += c[i - 1];
        for(int i = n; i >= 1; i--) sa[c[x[i]]--] = i;
        for(int k = 1; k <= n; k <<= 1) {
            int num = 0;
            for(int i = n - k + 1; i <= n; i++) y[++num] = i;
            for(int i = 1; i <= n; i++) if(sa[i] > k) y[++num] = sa[i] - k;
            for(int i = 1; i <= m; i++) c[i] = 0;
            for(int i = 1; i <= n; i++) c[x[i]]++;
            for(int i = 1; i <= m; i++) c[i] += c[i - 1];
            for(int i = n; i >= 1; i--) sa[c[x[y[i]]]--] = y[i], y[i] = 0;
            std::swap(x, y);
            x[sa[1]] = 1, num = 1;
            for(int i = 2; i <= n; i++) x[sa[i]] = (y[sa[i]] == y[sa[i - 1]] && y[sa[i] + k] == y[sa[i - 1] + k])? num : ++num;
            if(num == n) break;
            m = num;
        }
        for(int i = 1; i <= n; i++) rk[i] = x[i];
        int H = 0;
        for(int i = 1; i <= n; i++) {
            if(rk[i] == 1) continue;
            if(H) H--;
            int j = sa[rk[i] - 1];
            while(i + H <= n && j + H <= n && s[i + H] == s[j + H]) H++;
            h[rk[i]] = H;
        }
        for(int i = 1; i <= n; i++) st[i][0] = h[i];
        for(int j = 1; j <= 18; j++)
            for(int i = 1; i + (1 << j) - 1 <= n; i++)
                st[i][j] = std::min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
    int LCP(int x, int y) {
        x = rk[x], y = rk[y];
        if(x > y) std::swap(x, y);
        x++;
        int l = lg[y - x + 1];
        return std::min(st[x][l], st[y - (1 << l) + 1][l]);
    }
    void ins(char *s, int len) {
        n = len, m = 122;
        for(int i = 1; i <= n; i++) this->s[i] = s[i];
    }
}A, B;
LL pre[maxn], nxt[maxn];
char s[maxn];
int main() {
    lg[0] = -1;
    for(int i = 1; i < maxn; i++) lg[i] = lg[i >> 1] + 1;
    for(int T = in(); T --> 0;) {
        scanf("%s", s + 1);
        int n = strlen(s + 1);
        A.ins(s, n);
        std::reverse(s + 1, s + n + 1);
        B.ins(s, n);
        A.init(), B.init();
        memset(pre, 0, sizeof pre), memset(nxt, 0, sizeof nxt);
        for(int L = 1; L <= n >> 1; L++)
            for(int i = 1; i + L <= n; i += L) {
                int j = i + L;
                int xx = A.LCP(i, j), yy = B.LCP(n - i + 1, n - j + 1);
                xx = std::min(xx, L), yy = std::min(yy, L);
                if(xx + yy < L + 1) continue;
                int nowlen = xx + yy - L - 1;
                nxt[i - yy + 1]++, nxt[i - yy + nowlen + 2]--;
                pre[j + xx - nowlen - 1]++, pre[j + xx]--;
            }
        for(int i = 1; i <= n; i++) pre[i] += pre[i - 1], nxt[i] += nxt[i - 1];
        LL ans = 0;
        for(int i = 1; i < n; i++) ans += pre[i] * nxt[i + 1];
        printf("%lld\n", ans);
    }
    return 0;
}

