const int MAXN=3e4;
const int LOG_MAXN=15;

int n;
char s[MAXN+5];

struct SuffixArray{
	int n,m,x[MAXN+5],y[MAXN+5],c[MAXN+5],sa[MAXN+5];
	int rk[MAXN+5],ht[MAXN+5],st[MAXN+5][LOG_MAXN+5];
	int _log2[MAXN+5];
	void clear(){
		for(int i=1;i<=max(n,(int)'z');++i)c[i]=0;
		for(int i=1;i<=n;++i)y[i]=0;
	}
	void init(){
		_log2[0]=-1;
		for(int i=1;i<=MAXN;++i)_log2[i]=_log2[i>>1]+1;
	}
	void build(char* s,int _n){
		n=_n;
		m='z';
		for(int i=1;i<=n;++i)c[x[i]=s[i]]++;
		for(int i=1;i<=m;++i)c[i]+=c[i-1];
		for(int i=n;i>=1;--i)sa[c[x[i]]--]=i;
		for(int k=1;k<=n;k<<=1){
			int num=0;
			for(int i=n-k+1;i<=n;++i)y[++num]=i;
			for(int i=1;i<=n;++i)if(sa[i]>k)y[++num]=sa[i]-k;
			for(int i=1;i<=m;++i)c[i]=0;
			for(int i=1;i<=n;++i)c[x[i]]++;
			for(int i=1;i<=m;++i)c[i]+=c[i-1];
			for(int i=n;i>=1;--i)sa[c[x[y[i]]]--]=y[i];
			for(int i=1;i<=n;++i)swap(x[i],y[i]);
			x[sa[1]]=1;num=1;
			for(int i=2;i<=n;++i)
				x[sa[i]]=((y[sa[i]]==y[sa[i-1]] && y[sa[i]+k]==y[sa[i-1]+k])?num:++num);
			if(num==n)break;
			m=num;
		}
		for(int i=1;i<=n;++i)rk[sa[i]]=i;
		//for(int i=1;i<=n;++i)cout<<rk[i]<<" ";cout<<endl;
		int k=0;
		for(int i=1;i<=n;++i){
			if(rk[i]==1)continue;
			if(k)--k;
			int j=sa[rk[i]-1];
			while(i+k<=n && j+k<=n && s[i+k]==s[j+k]) ++k;
			ht[rk[i]]=k;
		}
		for(int i=1;i<=n;++i)st[i][0]=ht[i];
		for(int j=1;j<=LOG_MAXN;++j){
			for(int i=1;i+(1<<(j-1))<=n;++i){
				st[i][j]=min(st[i][j-1],st[i+(1<<(j-1))][j-1]);
			}
		}
	}
	int rmq(int l,int r){
		int k=_log2[r-l+1];
		return min(st[l][k],st[r-(1<<k)+1][k]);
	}
	int get_lcp(int i,int j){
		if(i==j) return n-i+1;
		i=rk[i];
		j=rk[j];
		if(i>j)swap(i,j);
		assert(i<j);
		return rmq(i+1,j);
	}
	SuffixArray(){}
};

SuffixArray SA,SA_rev;
int f[MAXN+5],g[MAXN+5];

void solve_case(){
	SA.clear();
	SA_rev.clear();
	cin>>(s+1);
	n=strlen(s+1);
	SA.build(s,n);
	reverse(s+1,s+n+1);
	SA_rev.build(s,n);

	for(int i=1;i<=n;++i)f[i]=g[i]=0;

	int maxlen=(n-2)/2;
	for(int len=1;len<=maxlen;++len){
		for(int k=1;(k+1)*len<=n;++k){
			int i=k*len;
			int j=(k+1)*len;
			int lcp=SA.get_lcp(i,j);
			int lcs=(i==1?0:SA_rev.get_lcp(n-(i-1)+1,n-(j-1)+1));
			if(!lcp)continue;
			int l=j-min(lcs,len-1)+len-1;
			int r=min(n,j+min(lcp,len)-1);
			if(l<=r){
				f[l]++;f[r+1]--;
			}
			l=max(1,i-min(lcs,len-1));
			r=i+min(lcp,len)-1-len+1;
			if(l<=r){
				g[l]++;g[r+1]--;
			}
		}
	}
	for(int i=1;i<=n;++i)f[i]+=f[i-1],g[i]+=g[i-1];
	f[n+1]=g[n+1]=0;
	ll ans=0;
	for(int i=1;i<=n-2;++i)
		ans+=(ll)f[i]*g[i+1];
	cout<<ans<<endl;
}

int main() {
	SA.init();
	SA_rev.init();
	int T;cin>>T;while(T--){
		solve_case();
	}
	return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int mod = 1e9 + 7;
const int maxn = 30005;

int a[maxn], b[maxn];
long long w[maxn], p[maxn];
char s[maxn];

inline int get(int l, int r) { //计算字符串中l~r段的哈希值
    return ((w[r] - w[l - 1] * p[r - l + 1]) % mod + mod) % mod;
}

int n, now;

int lcp(int x, int y) //求最长前缀
{
    int l = 0, r = now;
    while (l < r) {
        int mid = l + r + 1 >> 1;
        if (get(x - mid + 1, x) == get(y - mid + 1, y))
            l = mid;
        else
            r = mid - 1;
    }
    return l;
}

int lcs(int x, int y) //求最长后缀
{
    int l = 0, r = n - y + 1;
    while (l < r) {
        int mid = l + r + 1 >> 1;
        if (get(x, x + mid - 1) == get(y, y + mid - 1))
            l = mid;
        else
            r = mid - 1;
    }
    return l;
}

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        memset(a, 0, sizeof(a));
        memset(b, 0, sizeof(b));
        scanf("%s", s + 1);
        n = strlen(s + 1);
        p[0] = 1;
        for (int i = 1; i <= n; i++) { //字符串哈希
            p[i] = p[i - 1] * 31 % mod;
            w[i] = (w[i - 1] * 31 + s[i] - 'a') % mod;
        }
        for (int len = 1; len <= n; len++) { //从小到大枚举删除区间的长度
            int j = len, k = len << 1; //两个观察点
            now = len;
            while (k <= n) {
                int LCP = lcp(j, k), LCS = lcs(j, k);
                int hd = max(k - LCP + len, k), tl = min(k + LCS - 1, k + len - 1); //两个块的尾位置
                if (hd <= tl) {
                    a[hd]++, a[tl + 1]--; //两个尾部之间的空间
                    b[hd - len * 2 + 1]++, b[tl - len * 2 + 2]--; //两个头部之间的空间
                }
                j += len, k += len; //转移到下一个观察点
            }
        }
        for (int i = 1; i <= n; i++)
            a[i] += a[i - 1], b[i] += b[i - 1];
        long long answer = 0;
        for (int i = 1; i < n; i++)
            answer += a[i] * b[i + 1];
        printf("%lld\n", answer);
    }
    return 0;
}
